package org.sleepwell.app;
import org.junit.Test;import static org.junit.Assert.*;

public final class FlipSnoozeTest {
    long ms(long value){return value*1_000_000L;}boolean sample(FlipSnooze detector,long time,double z){return detector.sample(ms(time),ms(time),0,0,z);}
    void up(FlipSnooze detector,long start){for(long n=start;n<=start+400;n+=100)assertFalse(sample(detector,n,9.81));}
    @Test public void deliberateFaceUpThenSustainedFaceDownEmitsExactlyOnce(){FlipSnooze detector=new FlipSnooze();up(detector,0);for(long n=500;n<1300;n+=100)assertFalse(sample(detector,n,-9.81));assertTrue(sample(detector,1300,-9.81));assertFalse(sample(detector,1400,-9.81));assertFalse(sample(detector,1500,9.81));}
    @Test public void initiallyFaceDownAndFastShakeOrBriefFlipDoNotCount(){FlipSnooze detector=new FlipSnooze();for(long n=0;n<2000;n+=100)assertFalse(sample(detector,n,-9.81));up(detector,2000);for(long n=2500;n<2700;n+=100)assertFalse(sample(detector,n,-9.81));assertFalse(sample(detector,2700,9.81));assertFalse(detector.sample(ms(2800),ms(2800),18,0,-10));for(long n=2900;n<3600;n+=100)assertFalse(sample(detector,n,-9.81));}
    @Test public void oldFutureNonfiniteAndLongGapSamplesCannotCompleteTheGesture(){FlipSnooze detector=new FlipSnooze();up(detector,0);assertFalse(detector.sample(ms(500),ms(1100),0,0,-9.81));for(long n=1200;n<2400;n+=100)assertFalse(sample(detector,n,-9.81));up(detector,2400);assertFalse(detector.sample(ms(3000),ms(2999),0,0,-9.81));assertFalse(detector.sample(ms(3100),ms(3100),Double.NaN,0,-9.81));up(detector,3200);assertFalse(sample(detector,5000,-9.81));for(long n=5100;n<6200;n+=100)assertFalse(sample(detector,n,-9.81));}
    @Test public void duplicateOutOfOrderEventsAndInvertedSidewaysPhoneCannotInventHoldTime(){FlipSnooze detector=new FlipSnooze();up(detector,0);assertFalse(sample(detector,500,-9.81));assertFalse(sample(detector,500,-9.81));assertFalse(sample(detector,450,-9.81));assertFalse(detector.sample(ms(600),ms(600),6,0,-9.81));for(long n=700;n<1500;n+=100)assertFalse(sample(detector,n,-9.81));assertTrue(sample(detector,1500,-9.81));}
    @Test public void queuedEventsBeforeNewAdmissionCannotRequalifyAResumedGesture(){FlipSnooze detector=new FlipSnooze(ms(1000));for(long n=500;n<=900;n+=100)assertFalse(detector.sample(ms(n),ms(1000),0,0,9.81));for(long n=1000;n<2100;n+=100)assertFalse(sample(detector,n,-9.81));up(detector,2100);for(long n=2600;n<3400;n+=100)assertFalse(sample(detector,n,-9.81));assertTrue(sample(detector,3400,-9.81));assertThrows(IllegalArgumentException.class,()->new FlipSnooze(-1));}
}
